package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.level.storage.*;
import net.minecraft.util.ProblemReporter;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.research.*;
import thaumcraft.config.ThaumcraftConfig;
import thaumcraft.persistence.PlayerWarpStore;
@Mod.EventBusSubscriber(modid="thaumcraft")
public final class CheatSheetProbe {
 public static final BlockPos P=new BlockPos(69208,150,0);
 public static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 public static ServerPlayer player(ServerLevel l,String name){var p=new ServerPlayer(l.getServer(),l,new GameProfile(UUID.nameUUIDFromBytes(name.getBytes(java.nio.charset.StandardCharsets.UTF_8)),name),ClientInformation.createDefault());new net.minecraft.server.network.ServerGamePacketListenerImpl(l.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false)){@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet,io.netty.channel.ChannelFutureListener listener){}};p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);p.setPos(P.getX(),P.getY(),P.getZ());return p;}
 static void reset(ServerPlayer p){p.closeContainer();p.getInventory().clearContent();check(KnowledgeStore.write(p,KnowledgeState.EMPTY),"Reset knowledge failed");check(PlayerWarpStore.write(p,PlayerWarpStore.State.EMPTY).result().isPresent(),"Reset warp failed");}
 static InteractionResult use(ServerPlayer p,InteractionHand hand){return p.gameMode.useItem(p,p.level(),p.getItemInHand(hand),hand);}
 static int completed(ServerPlayer p){var s=ResearchService.state(p);return s==null?-1:(int)ResearchCatalog.ENTRIES.stream().filter(e->ResearchCatalog.knows(s,e.key())).count();}
 static void creative(ServerLevel l,boolean allowed){ThaumcraftConfig.allowCheatSheet.set(allowed);var tab=thaumcraft.content.BasicContent.TAB.get();tab.buildContents(new CreativeModeTab.ItemDisplayParameters(l.enabledFeatures(),false,l.registryAccess()));check(tab.getDisplayItems().stream().filter(CheatSheet::special).count()==(allowed?1:0),"Creative tab gate wrong");check(tab.getSearchTabDisplayItems().stream().filter(CheatSheet::special).count()==(allowed?1:0),"Creative search gate wrong");check(tab.getDisplayItems().stream().anyMatch(i->i.is(ResearchContent.BOOK.get())&&!CheatSheet.special(i)),"Normal book missing");}
 static void write(ServerLevel l){var p=player(l,"Cheat73Proof");reset(p);creative(l,false);p.setItemInHand(InteractionHand.MAIN_HAND,CheatSheet.stack());check(use(p,InteractionHand.MAIN_HAND).consumesAction()&&p.containerMenu instanceof ResearchMenu&&completed(p)<148,"Disabled special granted all research");check(PlayerWarpStore.read(p).getOrThrow().equals(PlayerWarpStore.State.EMPTY),"Disabled book added warp");reset(p);creative(l,true);var renamed=new ItemStack(ResearchContent.BOOK.get());renamed.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.translatable("item.thaumcraft.thaumonomicon_cheat"));p.setItemInHand(InteractionHand.MAIN_HAND,renamed);check(use(p,InteractionHand.MAIN_HAND).consumesAction()&&completed(p)<148,"Renaming normal book grants research");var forged=new ItemStack(Items.DIAMOND);forged.set(ResearchContent.CHEAT_SHEET.get(),net.minecraft.util.Unit.INSTANCE);p.setItemInHand(InteractionHand.MAIN_HAND,forged);check(!CheatSheet.grant(p,InteractionHand.MAIN_HAND),"Marker on another item grants research");thaumcraft.Thaumcraft.LOGGER.info("CHEAT73_GATE_OK: default disabled, tab/search visibility, disabled stored copy, renamed book and foreign marker");
 reset(p);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STONE,17));var item=CheatSheet.stack();p.setItemInHand(InteractionHand.OFF_HAND,item);p.experienceLevel=17;var prior=KnowledgeState.EMPTY.scan("item:minecraft:stone").craft("thaumcraft:thaumometer").flag("addon_flag").stage("addon_entry",3).addPoints("THEORY","BASICS",35);KnowledgeStore.write(p,prior);var plan=CheatResearch.complete(prior);check(use(p,InteractionHand.OFF_HAND).consumesAction()&&completed(p)==148&&p.containerMenu instanceof ResearchMenu,"Offhand real use did not grant/open all research");check(ResearchService.state(p).equals(plan.knowledge())&&p.getMainHandItem().getCount()==17&&CheatSheet.special(p.getOffhandItem())&&p.experienceLevel==17,"Cheat changed inventory, XP or independent knowledge");var warp=PlayerWarpStore.read(p).getOrThrow();check(warp.permanent()==plan.permanentWarp()&&warp.normal()==plan.normalWarp(),"Original warp not charged once");check(use(p,InteractionHand.OFF_HAND).consumesAction()&&PlayerWarpStore.read(p).getOrThrow().equals(warp)&&ResearchService.state(p).equals(plan.knowledge()),"Repeated use repeated warp or knowledge changes");var other=player(l,"Cheat73Other");check(completed(other)==0,"Cheat affected another player");var menu=(ResearchMenu)p.containerMenu;for(int i=0;i<148;i++)check(menu.visible(i)&&menu.stage(i)>ResearchCatalog.ENTRIES.get(i).stages().size(),"Menu incomplete entry "+i);for(int i=0;i<7;i++)check(menu.categoryUnlocked(i),"Menu category locked");creative(l,false);check(completed(p)==148,"Disabling option revoked existing research");creative(l,true);thaumcraft.Thaumcraft.LOGGER.info("CHEAT73_GRANT_OK: actual offhand use, all 148 entries and seven categories, no costs, preserved knowledge/XP/items, original warp once and player isolation");
 l.getChunkAt(P);l.setBlockAndUpdate(P,Blocks.CHEST.defaultBlockState());var chest=(ChestBlockEntity)l.getBlockEntity(P);chest.clearContent();chest.setItem(0,item.copy());var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,l.registryAccess());p.saveWithoutId(out);var save=new ItemStack(Items.PAPER);save.set(DataComponents.CUSTOM_DATA,CustomData.of(out.buildResult()));chest.setItem(1,save);chest.setChanged();
 var bad=player(l,"Cheat73Future");var future=new CompoundTag();future.putInt("version",2);future.putString("payload","preserve future research");bad.getPersistentData().put(KnowledgeStore.ID,future);bad.setItemInHand(InteractionHand.MAIN_HAND,CheatSheet.stack());check(use(bad,InteractionHand.MAIN_HAND)==InteractionResult.FAIL&&bad.getPersistentData().get(KnowledgeStore.ID).equals(future),"Future knowledge overwritten");bad.getPersistentData().remove(KnowledgeStore.ID);var futureWarp=new CompoundTag();futureWarp.putInt("version",2);futureWarp.putString("payload","preserve future warp");bad.getPersistentData().put(PlayerWarpStore.ID,futureWarp);check(use(bad,InteractionHand.MAIN_HAND)==InteractionResult.FAIL&&ResearchService.state(bad).equals(KnowledgeState.EMPTY)&&bad.getPersistentData().get(PlayerWarpStore.ID).equals(futureWarp),"Warp failure partially granted research");ThaumcraftConfig.wussMode.set(true);check(use(bad,InteractionHand.MAIN_HAND).consumesAction()&&completed(bad)==148&&bad.getPersistentData().get(PlayerWarpStore.ID).equals(futureWarp),"Wuss mode touched warp or blocked research");ThaumcraftConfig.wussMode.set(false);thaumcraft.Thaumcraft.LOGGER.info("CHEAT73_FUTURE_OK: future knowledge/warp preserved, no partial grant, wuss mode leaves warp untouched");thaumcraft.Thaumcraft.LOGGER.info("CHEAT73_WRITE_OK");}
 static void read(ServerLevel l){l.getChunkAt(P);var chest=(ChestBlockEntity)l.getBlockEntity(P);check(chest!=null&&CheatSheet.special(chest.getItem(0)),"Cold restart lost marked item");var p=player(l,"Cheat73Proof");p.load(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),chest.getItem(1).get(DataComponents.CUSTOM_DATA).copyTag()));check(completed(p)==148&&CheatSheet.special(p.getOffhandItem())&&ResearchService.state(p).flags().contains("addon_flag"),"Native player save/load lost research/marker");var warp=PlayerWarpStore.read(p).getOrThrow();ThaumcraftConfig.allowCheatSheet.set(true);check(use(p,InteractionHand.OFF_HAND).consumesAction()&&PlayerWarpStore.read(p).getOrThrow().equals(warp),"Restart use charged warp twice");thaumcraft.Thaumcraft.LOGGER.info("CHEAT73_RESTART_OK: second JVM recovers marked inventory, native full player data and research; use remains idempotent");}
 @SubscribeEvent public static void start(ServerStartedEvent e){String mode=System.getProperty("thaumcraft.bookProbe","");if(!Set.of("cheat-write","cheat-read").contains(mode))return;boolean allow=ThaumcraftConfig.allowCheatSheet.get(),wuss=ThaumcraftConfig.wussMode.get();e.getServer().tickRateManager().setFrozen(true);try{ThaumcraftConfig.wussMode.set(false);if(mode.endsWith("write"))write(e.getServer().overworld());else read(e.getServer().overworld());}finally{ThaumcraftConfig.allowCheatSheet.set(allow);ThaumcraftConfig.wussMode.set(wuss);}e.getServer().halt(false);}
}
